import json,numpy as np
x=json.load(open('/app/output/arm_calibration.json')); J=np.array(x['J_world']); q=np.array(x['q']); p=np.array(x['eef_xyz']); t=np.array([.355,-.154,1.206]);
for targ in [t, np.array([.355,-.154,1.235]), np.array([.356,-.143,1.11])]:
 qk=q.copy(); pk=p.copy(); print('target',targ)
 for k in range(12):
  dp=targ-pk; err=np.r_[dp,[0,0,0]]
  dq=J.T@np.linalg.solve(J@J.T+.025**2*np.eye(6),err)
  norm=np.max(np.abs(dq)); dq*=min(1,.1/max(norm,1e-9));
  qk+=dq; pk+=J[:3]@dq
  print(k, 'q',np.round(qk,2),'predpos',np.round(pk,3),'err',round(np.linalg.norm(targ-pk),3),'dqmax',round(np.max(abs(dq)),2))
  if np.linalg.norm(targ-pk)<.02:break
